$ErrorActionPreference = 'Stop'\n$Root = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path\n$EnvFile = Join-Path $Root '.env'\nif (-not (Test-Path $EnvFile)) { throw "Backend .env not found: $EnvFile" }\n$content = Get-Content $EnvFile -Raw\nfunction Set-EnvValue([string]$text,[string]$name,[string]$value) { $p='(?m)^'+[regex]::Escape($name)+'=.*$'; if([regex]::IsMatch($text,$p)){return [regex]::Replace($text,$p,"$name=$value")}; return $text.TrimEnd()+"`r`n$name=$value`r`n" }\n$content = Set-EnvValue $content 'ROUTING_MODE' 'self_hosted'\n$content = Set-EnvValue $content 'GRAPHHOPPER_SELF_HOSTED_URL' 'http://127.0.0.1:8989/route'\nSet-Content -Path $EnvFile -Value $content -NoNewline\nWrite-Host 'Self-hosted routing enabled in backend .env.'\n